     1→import { useCallback, useMemo } from "react";
     2→import { invoke } from "@tauri-apps/api/core";
     3→import { useQueryClient } from "@tanstack/react-query";
     4→import { getTabViewModel, useTabStore } from "@/stores/tab-store";
     5→import type { ListPagesResult, PageConfig } from "@/lib/gateway";
     6→import type { IconData } from "@/components/ui/icon-picker";
     7→import { resolveLocationNavigation } from "@/navigation/location-navigation";
     8→import {
     9→  type DesktopLocation,
    10→  type BreadcrumbStackItem,
    11→  type PushPageOptions,
    12→  type TabNavigationState,
    13→  locationToUrl,
    14→  urlToLocation,
    15→  normalizeSettingsSection,
    16→  normalizeWorkspaceSection,
    17→} from "@/navigation/navigation-meta";
    18→import { pageKeys } from "@/hooks/use-pages";
    19→import { useLocalWorkspaces } from "@/hooks/use-workspaces";
    20→import type { TabViewModel } from "@/stores/tab-store";
    21→
    22→// ─── Hook 1: useTabList ─────────────────────────────────────────────────────
    23→// Returns the tab view model list. Only re-renders when the tabs array changes.
    24→
    25→export function useTabList(): TabViewModel[] {
    26→  const rawTabs = useTabStore((state) => state.tabs);
    27→  return useMemo(() => rawTabs.map(getTabViewModel), [rawTabs]);
    28→}
    29→
    30→// ─── Hook 2: useActiveTabState ──────────────────────────────────────────────
    31→// Returns reactive state about the active tab. Re-renders when active tab changes.
    32→
    33→export interface ActiveTabState {
    34→  activeTabId: string | null;
    35→  activeTab: TabViewModel | null;
    36→  canGoBack: boolean;
    37→  canGoForward: boolean;
    38→  currentUrl: string | null;
    39→  currentNavigationState: TabNavigationState | null;
    40→}
    41→
    42→export function useActiveTabState(): ActiveTabState {
    43→  const activeTabId = useTabStore((state) => state.activeTabId);
    44→  const activeTabRaw = useTabStore((state) =>
    45→    state.tabs.find((tab) => tab.id === state.activeTabId) ?? null
    46→  );
    47→  const canGoBackFn = useTabStore((state) => state.canGoBack);
    48→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
    49→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
    50→  const getCurrentNavigationState = useTabStore(
    51→    (state) => state.getCurrentNavigationState
    52→  );
    53→
    54→  const activeTab = useMemo(
    55→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    56→    [activeTabRaw]
    57→  );
    58→
    59→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    60→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    61→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    62→  const currentNavigationState = activeTabId
    63→    ? getCurrentNavigationState(activeTabId)
    64→    : null;
    65→
    66→  return useMemo(
    67→    () => ({
    68→      activeTabId,
    69→      activeTab,
    70→      canGoBack,
    71→      canGoForward,
    72→      currentUrl,
    73→      currentNavigationState,
    74→    }),
    75→    [activeTabId, activeTab, canGoBack, canGoForward, currentUrl, currentNavigationState]
    76→  );
    77→}
    78→
    79→// ─── Hook 3: useTabActions ──────────────────────────────────────────────────
    80→// Returns stable action functions for tab operations. These reference Zustand
    81→// store actions + resolve navigation logic. Actions that depend on activeTabId
    82→// will have their identity change when activeTabId changes.
    83→
    84→export interface TabActions {
    85→  openLocation: (
    86→    location: DesktopLocation,
    87→    options?: { breadcrumbStack?: BreadcrumbStackItem[]; openInNewTab?: boolean }
    88→  ) => string;
    89→  replaceLocation: (
    90→    location: DesktopLocation,
    91→    patch?: Partial<TabNavigationState>
    92→  ) => string | undefined;
    93→  pushLocation: (
    94→    location: DesktopLocation,
    95→    patch?: Partial<TabNavigationState>
    96→  ) => string | undefined;
    97→  pushPage: (
    98→    item: BreadcrumbStackItem,
    99→    nextLocation: DesktopLocation,
   100→    options?: PushPageOptions
   101→  ) => string | undefined;
   102→  popTo: (index: number) => void;
   103→  resetStack: (next: TabNavigationState) => string | undefined;
   104→  navigateTo: (
   105→    url: string,
   106→    input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }
   107→  ) => string | undefined;
   108→  openPageTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   109→  openPageInNewTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   110→  openWorkspaceView: (workspaceId: string, viewPath: string, viewName: string, icon: IconData) => string;
   111→  openGlobalView: (path: string, name: string, icon: IconData) => string;
   112→  openWebUrl: (url: string, title?: string, workspaceId?: string) => string;
   113→  openChatTab: (chatId: string, chatName: string, workspaceId: string) => string;
   114→  switchToTab: (tabId: string) => string | null;
   115→  closeTab: (tabId: string) => void;
   116→  detachTabToNewWindow: (tabId: string) => Promise<boolean>;
   117→  getTabLink: (tabId: string) => string | null;
   118→}
   119→
   120→export function useTabActions(): TabActions {
   121→  const queryClient = useQueryClient();
   122→  const { getWorkspace } = useLocalWorkspaces();
   123→  const activeTabId = useTabStore((state) => state.activeTabId);
   124→  const rawTabs = useTabStore((state) => state.tabs);
   125→
   126→  const openTab = useTabStore((state) => state.openTab);
   127→  const closeTabStore = useTabStore((state) => state.closeTab);
   128→  const setActiveTab = useTabStore((state) => state.setActiveTab);
   129→  const replaceLocationStore = useTabStore((state) => state.replaceLocation);
   130→  const pushLocationStore = useTabStore((state) => state.pushLocation);
   131→  const pushPageStore = useTabStore((state) => state.pushPage);
   132→  const popToStore = useTabStore((state) => state.popTo);
   133→  const resetStackStore = useTabStore((state) => state.resetStack);
   134→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
   135→  const getCurrentNavigationState = useTabStore(
   136→    (state) => state.getCurrentNavigationState
   137→  );
   138→
   139→  const resolveNavigation = useCallback(
   140→    (
   141→      location: DesktopLocation,
   142→      input?: {
   143→        breadcrumbStack?: BreadcrumbStackItem[];
   144→        title?: string;
   145→        icon?: IconData;
   146→        workspaceId?: string;
   147→      }
   148→    ) => {
   149→      const workspaceId =
   150→        input?.workspaceId ?? ("workspaceId" in location ? location.workspaceId : undefined);
   151→      const workspace = workspaceId ? getWorkspace(workspaceId) : undefined;
   152→      const cachedPages = workspace?.path
   153→        ? queryClient.getQueryData<ListPagesResult | PageConfig[]>(
   154→            pageKeys.list(workspace.path)
   155→          )
   156→        : undefined;
   157→      const pages = Array.isArray(cachedPages)
   158→        ? cachedPages
   159→        : cachedPages?.pages;
   160→
   161→      return resolveLocationNavigation({
   162→        location,
   163→        workspace,
   164→        pages,
   165→        breadcrumbStack: input?.breadcrumbStack,
   166→        title: input?.title,
   167→        icon: input?.icon,
   168→      });
   169→    },
   170→    [getWorkspace, queryClient]
   171→  );
   172→
   173→  const openLocation = useCallback(
   174→    (
   175→      location: DesktopLocation,
   176→      options?: {
   177→        breadcrumbStack?: BreadcrumbStackItem[];
   178→        openInNewTab?: boolean;
   179→      }
   180→    ) => {
   181→      const resolvedNavigation = resolveNavigation(location, {
   182→        breadcrumbStack: options?.breadcrumbStack,
   183→      });
   184→      const navigationState: TabNavigationState = {
   185→        location,
   186→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
   187→      };
   188→
   189→      if (options?.openInNewTab || !activeTabId) {
   190→        return openTab({
   191→          navigationState,
   192→          pinned: false,
   193→        });
   194→      }
   195→
   196→      replaceLocationStore(activeTabId, navigationState);
   197→      return activeTabId;
   198→    },
   199→    [activeTabId, openTab, replaceLocationStore, resolveNavigation]
   200→  );
   201→
   202→  const replaceLocation = useCallback(
   203→    (
   204→      location: DesktopLocation,
   205→      patch?: Partial<TabNavigationState>
   206→    ) => {
   207→      if (!activeTabId) {
   208→        return openLocation(location, {
   209→          breadcrumbStack: patch?.breadcrumbStack,
   210→          openInNewTab: true,
   211→        });
   212→      }
   213→
   214→      const resolvedNavigation = resolveNavigation(location, {
   215→        breadcrumbStack: patch?.breadcrumbStack,
   216→      });
   217→      replaceLocationStore(activeTabId, {
   218→        location,
   219→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
   220→        activeIndexPath: patch?.activeIndexPath,
   221→        activeNodeId: patch?.activeNodeId,
   222→      });
   223→      return activeTabId;
   224→    },
   225→    [activeTabId, openLocation, replaceLocationStore, resolveNavigation]
   226→  );
   227→
   228→  const pushLocation = useCallback(
   229→    (
   230→      location: DesktopLocation,
   231→      patch?: Partial<TabNavigationState>
   232→    ) => {
   233→      if (!activeTabId) {
   234→        return openLocation(location, {
   235→          breadcrumbStack: patch?.breadcrumbStack,
   236→          openInNewTab: true,
   237→        });
   238→      }
   239→
   240→      const resolvedNavigation = resolveNavigation(location, {
   241→        breadcrumbStack: patch?.breadcrumbStack,
   242→      });
   243→      pushLocationStore(activeTabId, {
   244→        location,
   245→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
   246→        activeIndexPath: patch?.activeIndexPath,
   247→        activeNodeId: patch?.activeNodeId,
   248→      });
   249→      return activeTabId;
   250→    },
   251→    [activeTabId, openLocation, pushLocationStore, resolveNavigation]
   252→  );
   253→
   254→  const pushPage = useCallback(
   255→    (
   256→      item: BreadcrumbStackItem,
   257→      nextLocation: DesktopLocation,
   258→      options?: PushPageOptions
   259→    ) => {
   260→      if (!activeTabId) {
   261→        const resolvedNavigation = resolveNavigation(nextLocation, {
   262→          title: item.label,
   263→          icon: item.icon,
   264→        });
   265→        return openLocation(nextLocation, {
   266→          breadcrumbStack: [...resolvedNavigation.breadcrumbStack, item],
   267→          openInNewTab: true,
   268→        });
   269→      }
   270→
   271→      pushPageStore(activeTabId, item, nextLocation, options);
   272→      return activeTabId;
   273→    },
   274→    [activeTabId, openLocation, pushPageStore, resolveNavigation]
   275→  );
   276→
   277→  const popTo = useCallback(
   278→    (index: number) => {
   279→      if (!activeTabId) return;
   280→      popToStore(activeTabId, index);
   281→    },
   282→    [activeTabId, popToStore]
   283→  );
   284→
   285→  const resetStack = useCallback(
   286→    (next: TabNavigationState) => {
   287→      if (!activeTabId) {
   288→        return openLocation(next.location, {
   289→          breadcrumbStack: next.breadcrumbStack,
   290→          openInNewTab: true,
   291→        });
   292→      }
   293→
   294→      resetStackStore(activeTabId, next);
   295→      return activeTabId;
   296→    },
   297→    [activeTabId, openLocation, resetStackStore]
   298→  );
   299→
   300→  const navigateTo = useCallback(
   301→    (url: string, input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }) => {
   302→      const isExternal = url.startsWith("http://") || url.startsWith("https://");
   303→      if (isExternal) {
   304→        const workspaceId = input.meta?.workspaceId ?? "global";
   305→        return openLocation(
   306→          {
   307→            kind: "workspace-web",
   308→            workspaceId,
   309→            url,
   310→            title: input.label,
   311→          },
   312→          { openInNewTab: false }
   313→        );
   314→      }
   315→
   316→      if (activeTabId) {
   317→        const location = buildLocationFromLegacyUrl(url);
   318→        const resolvedNavigation = resolveNavigation(location, {
   319→          title: input.label,
   320→          icon: input.icon,
   321→          workspaceId: input.meta?.workspaceId,
   322→        });
   323→        replaceLocationStore(activeTabId, {
   324→          location,
   325→          breadcrumbStack: resolvedNavigation.breadcrumbStack,
   326→        });
   327→        return activeTabId;
   328→      }
   329→
   330→      const location = buildLocationFromLegacyUrl(url);
   331→      const resolvedNavigation = resolveNavigation(location, {
   332→        title: input.label,
   333→        icon: input.icon,
   334→        workspaceId: input.meta?.workspaceId,
   335→      });
   336→      return openTab({
   337→        pinned: false,
   338→        navigationState: {
   339→          location,
   340→          breadcrumbStack: resolvedNavigation.breadcrumbStack,
   341→        },
   342→      });
   343→    },
   344→    [activeTabId, openLocation, openTab, replaceLocationStore, resolveNavigation]
   345→  );
   346→
   347→  const openPageTab = useCallback(
   348→    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) =>
   349→      openLocation(
   350→        { kind: "workspace-page", workspaceId, pageSlug: page.slug },
   351→        { breadcrumbStack }
   352→      ),
   353→    [openLocation]
   354→  );
   355→
   356→  const openPageInNewTab = useCallback(
   357→    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) =>
   358→      openLocation(
   359→        { kind: "workspace-page", workspaceId, pageSlug: page.slug },
   360→        { openInNewTab: true, breadcrumbStack }
   361→      ),
   362→    [openLocation]
   363→  );
   364→
   365→  const openWorkspaceView = useCallback(
   366→    (workspaceId: string, viewPath: string, _viewName: string, _icon: IconData) => {
   367→      if (!viewPath) {
   368→        return openLocation({ kind: "workspace-home", workspaceId });
   369→      }
   370→      return openLocation({
   371→        kind: "workspace-section",
   372→        workspaceId,
   373→        section: normalizeWorkspaceSection(viewPath),
   374→      });
   375→    },
   376→    [openLocation]
   377→  );
   378→
   379→  const openGlobalView = useCallback(
   380→    (path: string, _name: string, _icon: IconData) => {
   381→      const location = buildLocationFromLegacyUrl(path);
   382→      return openLocation(location);
   383→    },
   384→    [openLocation]
   385→  );
   386→
   387→  const openWebUrl = useCallback(
   388→    (url: string, title?: string, workspaceId?: string) => {
   389→      const activeState = activeTabId ? getCurrentNavigationState(activeTabId) : null;
   390→      const activeLeaf = activeState?.breadcrumbStack[activeState.breadcrumbStack.length - 1];
   391→      const wsId =
   392→        workspaceId ??
   393→        (activeState?.location && "workspaceId" in activeState.location
   394→          ? activeState.location.workspaceId
   395→          : undefined) ??
   396→        activeLeaf?.meta?.workspaceId ??
   397→        "global";
   398→      return openLocation({
   399→        kind: "workspace-web",
   400→        workspaceId: wsId,
   401→        title: title ?? safeHostname(url),
   402→        url,
   403→      });
   404→    },
   405→    [activeTabId, getCurrentNavigationState, openLocation]
   406→  );
   407→
   408→  const openChatTab = useCallback(
   409→    (_chatId: string, _chatName: string, workspaceId: string) =>
   410→      openLocation({
   411→        kind: "workspace-section",
   412→        workspaceId,
   413→        section: "chat",
   414→      }),
   415→    [openLocation]
   416→  );
   417→
   418→  const switchToTab = useCallback(
   419→    (tabId: string) => {
   420→      setActiveTab(tabId);
   421→      return getCurrentUrl(tabId);
   422→    },
   423→    [getCurrentUrl, setActiveTab]
   424→  );
   425→
   426→  const closeTab = useCallback(
   427→    (tabId: string) => {
   428→      closeTabStore(tabId);
   429→    },
   430→    [closeTabStore]
   431→  );
   432→
   433→  const getTabLink = useCallback(
   434→    (tabId: string) => {
   435→      const state = getCurrentNavigationState(tabId);
   436→      return state ? locationToUrl(state.location) : null;
   437→    },
   438→    [getCurrentNavigationState]
   439→  );
   440→
   441→  const detachTabToNewWindow = useCallback(
   442→    async (tabId: string) => {
   443→      const tab = rawTabs.find((item) => item.id === tabId);
   444→      const state = getCurrentNavigationState(tabId);
   445→      const tabView = tab ? getTabViewModel(tab) : null;
   446→
   447→      if (!tab || !state || !("workspaceId" in state.location)) {
   448→        return false;
   449→      }
   450→
   451→      if (state.location.kind === "workspace-page") {
   452→        const workspace = getWorkspace(state.location.workspaceId);
   453→        if (!workspace?.path) {
   454→          return false;
   455→        }
   456→
   457→        await invoke("open_workspace_page_preview_window", {
   458→          workspaceId: state.location.workspaceId,
   459→          workspacePath: workspace.path,
   460→          slug: state.location.pageSlug,
   461→          title: tabView?.label ?? state.location.pageSlug,
   462→          view: tab.viewMode ?? "page",
   463→        });
   464→        closeTabStore(tabId);
   465→        return true;
   466→      }
   467→
   468→      const routePath = locationToUrl(state.location);
   469→      await invoke("open_workspace_in_new_window", {
   470→        workspaceId: state.location.workspaceId,
   471→        routePath,
   472→        title: tabView?.label ?? routePath,
   473→      });
   474→      closeTabStore(tabId);
   475→      return true;
   476→    },
