   575→// ─── Composed hook: usePageTabs (backward-compatible) ───────────────────────
   576→// Composes the 4 granular hooks. Existing consumers can continue using this
   577→// without changes, but new code should prefer the granular hooks.
   578→
   579→export function usePageTabs() {
   580→  const tabs = useTabList();
   581→  const activeState = useActiveTabState();
   582→  const actions = useTabActions();
   583→  const navigation = useTabNavigation();
   584→
   585→  return useMemo(
   586→    () => ({
   587→      tabs,
   588→      ...activeState,
   589→      ...actions,
   590→      ...navigation,
   591→    }),
   592→    [tabs, activeState, actions, navigation]
   593→  );
   594→}
