   489→export function locationToUrl(location: DesktopLocation): string {
   490→  switch (location.kind) {
   491→    case "workspace-home":
   492→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}`, location);
   493→    case "workspace-apps":
   494→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/apps`, location);
   495→    case "workspace-section":
   496→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/${location.section}`, location);
   497→    case "workspace-agent-detail":
   498→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/agent/${encodeURIComponent(location.agentId)}`, location);
   499→    case "workspace-executor-detail":
   500→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/executor/${encodeURIComponent(location.executorType)}`, location);
   501→    case "workspace-page": {
   502→      const encodedSlug = location.pageSlug.split("/").filter(Boolean).map((segment) => encodeURIComponent(segment)).join("/");
   503→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/page/${encodedSlug}`, location);
   504→    }
   505→    case "workspace-web": {
   506→      const params = new URLSearchParams({ url: location.url, title: location.title });
   507→      if (location.sourcePageSlug) params.set("source_page", location.sourcePageSlug);
   508→      if (location.webId) params.set("web_id", location.webId);
   509→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/web?${params.toString()}`, location);
   510→    }
   511→    case "agent-detail":
   512→      return appendUrlSuffix(`/agent/${encodeURIComponent(location.agentId)}${buildDetailQuery(location.workspacePath)}`, location);
   513→    case "executor-detail":
   514→      return appendUrlSuffix(`/executor/${encodeURIComponent(location.executorType)}${buildDetailQuery(location.workspacePath)}`, location);
   515→    case "skill-detail":
   516→      return appendUrlSuffix(`/skill/${encodeURIComponent(location.skillId)}${buildDetailQuery(location.workspacePath, { agent_id: location.agentId })}`, location);
   517→    case "mcp-server-detail":
   518→      return appendUrlSuffix(`/mcp-server/${encodeURIComponent(location.serverName)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   519→    case "subagent-detail":
   520→      return appendUrlSuffix(`/subagent/${encodeURIComponent(location.configId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   521→    case "prompt-detail":
   522→      return appendUrlSuffix(`/prompt/${encodeURIComponent(location.promptId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   523→    case "command-detail":
   524→      return appendUrlSuffix(`/command/${encodeURIComponent(location.commandId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   525→    case "settings":
   526→      return appendUrlSuffix(location.section ? `/settings/${encodeURIComponent(location.section)}` : "/settings/general", location);
   527→    case "documents":
   528→      return appendUrlSuffix("/documents", location);
   529→    case "device-pair":
   530→      return appendUrlSuffix("/devices/pair", location);
   531→    case "global-route":
   532→      return location.path;
   533→    default: {
   534→      const exhaustive: never = location;
   535→      return exhaustive;
   536→    }
   537→  }
   538→}
