   540→export function urlToLocation(url: string): DesktopLocation | null {
   541→  const parsed = new URL(url, "http://desktop.local");
   542→  const pathname = parsed.pathname;
   543→  const segments = pathname.split("/").filter(Boolean);
   544→  const suffix = { search: parsed.search || undefined, hash: parsed.hash || undefined };
   545→
   546→  if (pathname === "/documents") return { kind: "documents", ...suffix };
   547→  if (pathname === "/devices/pair") return { kind: "device-pair", ...suffix };
   548→  if (pathname === "/publish" || pathname === "/my-packages" || pathname === "/analytics") {
   549→    return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   550→  }
   551→
   552→  if (segments[0] === "settings") {
   553→    const section = normalizeSettingsSection(segments[1] ? decodePathPart(segments[1]) : "general");
   554→    return { kind: "settings", section, ...suffix };
   555→  }
   556→
   557→  if (segments[0] === "agent" && segments[1]) {
   558→    return { kind: "agent-detail", agentId: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   559→  }
   560→  if (segments[0] === "executor" && segments[1]) {
   561→    return { kind: "executor-detail", executorType: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   562→  }
   563→  if (segments[0] === "skill" && segments[1]) {
   564→    return { kind: "skill-detail", skillId: decodePathPart(segments[1]), agentId: parsed.searchParams.get("agent_id") ?? "", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   565→  }
   566→  if (segments[0] === "mcp-server" && segments[1]) {
   567→    return { kind: "mcp-server-detail", serverName: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   568→  }
   569→  if (segments[0] === "subagent" && segments[1]) {
   570→    return { kind: "subagent-detail", configId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   571→  }
   572→  if (segments[0] === "prompt" && segments[1]) {
   573→    return { kind: "prompt-detail", promptId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   574→  }
   575→  if (segments[0] === "command" && segments[1]) {
   576→    return { kind: "command-detail", commandId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   577→  }
   578→
   579→  if (segments[0] === "workspace" && segments[1] === "page") {
   580→    const workspaceId = parsed.searchParams.get("workspace_id");
   581→    const pageSlug = extractLegacyPageSlug(parsed.searchParams.get("page_path"));
   582→    if (workspaceId && pageSlug) {
   583→      return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   584→    }
   585→  }
   586→
   587→  if (segments[0] === "workspace" && segments[1]) {
   588→    const workspaceId = decodePathPart(segments[1]);
   589→    if (segments.length === 2) return { kind: "workspace-home", workspaceId, ...suffix };
   590→    if (segments[2] === "apps" && !segments[3]) return { kind: "workspace-apps", workspaceId, ...suffix };
   591→    if (segments[2] === "agents" && !segments[3]) return { kind: "workspace-section", workspaceId, section: "agent", ...suffix };
   592→    if (segments[2] === "agent" && segments[3]) return { kind: "workspace-agent-detail", workspaceId, agentId: decodePathPart(segments[3]), ...suffix };
   593→    if (segments[2] === "executor" && segments[3]) return { kind: "workspace-executor-detail", workspaceId, executorType: decodePathPart(segments[3]), ...suffix };
   594→    if (segments[2] === "web") {
   595→      const targetUrl = parsed.searchParams.get("url");
   596→      const title = parsed.searchParams.get("title");
   597→      if (targetUrl && title) {
   598→        return { kind: "workspace-web", workspaceId, url: targetUrl, title, sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined, webId: parsed.searchParams.get("web_id") ?? undefined, hash: parsed.hash || undefined };
   599→      }
   600→    }
   601→    if (segments[2] === "page") {
   602→      const pageSlug = extractWorkspacePageSlug(pathname);
   603→      if (pageSlug) return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   604→    }
   605→    const section = decodePathPart(segments[2]);
   606→    if (isWorkspaceSection(section)) return { kind: "workspace-section", workspaceId, section, ...suffix };
   607→  }
   608→
   609→  if (pathname === "/") return null;
   610→  return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   611→}
