    66→function decodePageSlug(raw: string): string {
    67→  return raw
    68→    .replace(/^pages\//, "")
    69→    .replace(/\/SKILL\.md$/i, "")
    70→    .replace(/^\//, "")
    71→    .trim();
    72→}
