    84→function pushUnique(items: ExtractedNavigationItem[], item: ExtractedNavigationItem) {
    85→  const exists = items.some((candidate) => {
    86→    if (candidate.kind !== item.kind) return false;
    87→    if (candidate.pageSlug && item.pageSlug) return candidate.pageSlug === item.pageSlug;
    88→    if (candidate.url && item.url) return candidate.url === item.url;
    89→    return candidate.id === item.id;
    90→  });
    91→  if (!exists) items.push(item);
